import { Table, TranslatedTextColumn, StringColumn, GuidColumn } from '@servicenow/sdk/core'

export const sys_notification_category = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Notification Category',
    name: 'sys_notification_category',
    schema: {
        name: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Name',
            mandatory: true,
            maxLength: 32,
            unique: true,
        }),
        short_description: StringColumn({
            label: 'Short description',
            maxLength: 1000,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
    textIndex: true,
})
